import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { SourceTextModule, SyntheticModule } from 'node:vm';

const events = [];
let failAt;
const failure = new Error('expected failure');
const record = (stage, ...args) => {
  events.push([stage, ...args]);
  if (failAt === stage) throw failure;
};
const dependencies = {
  './store.js': {
    saveReport: async (...args) => record('save', ...args),
    loadReport: async (...args) => { record('load', ...args); return 'stored copy'; },
  },
  './mail.js': { sendMail: async (...args) => record('mail', ...args) },
  './report_render.js': Object.fromEntries(['Daily', 'Weekly', 'Correction'].map(kind => [
    "'`render${kind}`, (...args) => { record('"'render', kind, ...args); return "'`rendered ${kind}`; },
  ])),
};
const mailer = new SourceTextModule(await readFile('"'src/report_mailer.js', 'utf8'));
await mailer.link(specifier => {
  const exports = dependencies[specifier];
  return new SyntheticModule(Object.keys(exports), function () {
    for (const [name, value] of Object.entries(exports)) this.setExport(name, value);
  });
});
await mailer.evaluate();
assert.deepEqual(Object.keys(mailer.namespace).sort(), ['sendCorrection', 'sendDailyReport', 'sendWeeklyReport']);
const shop = { id: 'shop-1', email: 'shop@example.invalid' };
const rows = [{ item: 'Coffee', cents: 300 }];
for (const [name, kind, renderedKind, subject, extra] of [
  ['sendDailyReport', 'daily', 'Daily', 'Your report for 2026-10-23', []],
  ['sendWeeklyReport', 'weekly', 'Weekly', 'Your report for the week of 2026-10-23', []],
  ['sendCorrection', 'correction', 'Correction', 'Corrected report for 2026-10-23', ['Updated total']],
]) {
  events.length = 0;
  const html = "'`rendered ${renderedKind}`;
  const key = `${kind}-shop-1-2026-10-23`;
  const invoke = () => mailer.namespace[name](shop, rows, '"'2026-10-23', ...extra);
  assert.deepEqual(await invoke(), { shopId: shop.id, kind, bytes: html.length });
  assert.deepEqual(events, [
    ['render', renderedKind, shop, rows, '2026-10-23', ...extra],
    ['save', key, html], ['load', key],
    ['mail', shop.email, subject, 'stored copy'],
  ]);
  for (const stage of ['render', 'save', 'load', 'mail']) {
    events.length = 0;
    failAt = stage;
    await assert.rejects(invoke(), error => error === failure);
    assert.deepEqual(events.map(event => event[0]), ['render', 'save', 'load', 'mail'].slice(0, ['render', 'save', 'load', 'mail'].indexOf(stage) + 1));
  }
  failAt = undefined;
}
console.log('All three send functions preserve arguments, results, stored-copy delivery, operation counts, and failure propagation.');
